changeSet.sql:
CREATE OR REPLACE TRIGGER trg_incidencia_adjunto_no_delete
BEFORE DELETE ON incidencia_adjunto
BEGIN
    RAISE_APPLICATION_ERROR(-20980, 'El adjunto de una incidencia no admite borrado fisico');
END;

CREATE OR REPLACE TRIGGER trg_incidencia_adjunto_vinculo
BEFORE UPDATE OF incident_id, storage_key, file_checksum ON incidencia_adjunto
BEGIN
    RAISE_APPLICATION_ERROR(-20981, 'El adjunto no admite desvinculacion ni sustitucion: incident_id, storage_key y file_checksum son inmutables');
END;
